import { useEffect, useMemo, useState } from 'react'
import { api, pollOCR, setToken } from './api/client'
import type { DobroResponse, Donor, IntervalCalendar, MemoRequest, OCRTask } from './api/types'

type Tab = 'registry' | 'certificate' | 'documents'
type Tone = 'good' | 'warn' | 'bad' | 'muted'
const tabs: { id: Tab; label: string; icon: string }[] = [
  { id: 'registry', label: 'Реестр доноров', icon: '◎' },
  { id: 'certificate', label: 'Обработать справку', icon: '▣' },
  { id: 'documents', label: 'Документы', icon: '▤' },
]
const fmtDate = (v?: string | null) => v ? new Intl.DateTimeFormat('ru-RU').format(new Date(v)) : '—'
const apiDetailText = (value: unknown): string => { if (typeof value === 'string') return value; if (Array.isArray(value)) return value.map(apiDetailText).filter(Boolean).join('; '); if (value && typeof value === 'object') { const detail = value as Record<string, unknown>; if (typeof detail.msg === 'string') return detail.msg; if (typeof detail.message === 'string') return detail.message; return Object.entries(detail).map(([key, item]) => `${key}: ${apiDetailText(item)}`).join(', ') }; return '' }
const errText = (e: unknown) => { if (e instanceof Error) { try { const parsed = JSON.parse(e.message); const text = apiDetailText(parsed); if (text) return text } catch { /* plain error message */ } return e.message || 'Не удалось выполнить запрос' }; return apiDetailText(e) || 'Не удалось выполнить запрос' }
const statusLabel = (v: string) => ({ active: 'Активен', graduate: 'Выпускник', archived: 'Архив', graduated: 'Выпускник', suspended: 'На паузе' } as Record<string, string>)[v.toLowerCase()] || v

function Badge({ children, tone = 'muted' }: { children: React.ReactNode; tone?: Tone }) {
  const styles = { good: 'bg-[#d9f5e8] text-[#14754b]', warn: 'bg-[#fff0c7] text-[#8d6500]', bad: 'bg-[#ffe0dc] text-[#b54338]', muted: 'bg-[#edf1f4] text-[#617181]' }
  return <span className={`inline-flex rounded-full px-2.5 py-1 text-[11px] font-bold ${styles[tone]}`}>{children}</span>
}
function Spinner() { return <span className="inline-block h-4 w-4 animate-spin rounded-full border-2 border-current border-r-transparent" aria-label="Загрузка" /> }
function Empty({ title, text }: { title: string; text: string }) { return <div className="rounded-2xl border border-dashed border-[#d5dee4] bg-white px-6 py-14 text-center"><div className="mx-auto mb-3 flex h-11 w-11 items-center justify-center rounded-full bg-[#edf3f3] text-xl text-[#168e78]">⌁</div><h3 className="font-bold text-[#263847]">{title}</h3><p className="mt-1 text-sm text-[#778795]">{text}</p></div> }
function Stat({ value, label, detail, tone = 'teal' }: { value: string; label: string; detail: string; tone?: 'teal' | 'orange' | 'blue' }) { const colors = { teal: 'bg-[#dff5ee] text-[#11856f]', orange: 'bg-[#fff0d4] text-[#bd741b]', blue: 'bg-[#e3effa] text-[#37749f]' }; return <div className="flex items-start gap-3 rounded-2xl border border-[#e2e9ed] bg-white p-4"><div className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl text-lg font-bold ${colors[tone]}`}>{value}</div><div><p className="text-[11px] font-bold uppercase tracking-[.12em] text-[#8795a0]">{label}</p><p className="mt-1 text-sm font-semibold text-[#334957]">{detail}</p></div></div> }

function Eligibility({ calendar, loading, error }: { calendar?: IntervalCalendar; loading: boolean; error?: string }) {
  if (loading) return <span className="flex items-center gap-2 text-xs text-[#8a98a2]"><Spinner /> расчёт</span>
  if (error || !calendar?.intervals.length) return <span className="flex items-center gap-2 text-xs text-[#8a98a2]"><i className="h-2.5 w-2.5 rounded-full bg-[#cbd5db]" /> нет данных</span>
  const i = calendar.intervals[0]; const today = new Date(); today.setHours(0, 0, 0, 0); const eligible = new Date(i.eligible_from) <= today && !i.annual_limit_reached
  const tone: Tone = i.annual_limit_reached ? 'bad' : eligible ? 'good' : 'warn'
  return <div className="flex items-center gap-2"><i className={`h-3 w-3 rounded-full ${tone === 'good' ? 'bg-[#24ad71] shadow-[0_0_0_4px_#d9f5e8]' : tone === 'warn' ? 'bg-[#e1a928] shadow-[0_0_0_4px_#fff0c7]' : 'bg-[#e05b4f] shadow-[0_0_0_4px_#ffe0dc]'}`} /><div><p className={`text-xs font-bold ${tone === 'good' ? 'text-[#14754b]' : tone === 'warn' ? 'text-[#8d6500]' : 'text-[#b54338]'}`}>{eligible ? 'Допущен' : i.annual_limit_reached ? 'Лимит исчерпан' : 'Медотвод'}</p><p className="mt-0.5 text-[11px] text-[#8997a0]">{eligible ? 'можно записывать' : `с ${fmtDate(i.eligible_from)}`}</p></div></div>
}

function Registry({ onSelect }: { onSelect: (donor: Donor) => void }) {
  const [page, setPage] = useState(0), [query, setQuery] = useState(''), [data, setData] = useState<{ items: Donor[]; total: number }>(), [loading, setLoading] = useState(true), [error, setError] = useState(''), [calendars, setCalendars] = useState<Record<string, IntervalCalendar>>({}), [intervalErrors, setIntervalErrors] = useState<Record<string, string>>({}); const limit = 8
  useEffect(() => { let cancelled = false; setLoading(true); api.donors({ limit, offset: page * limit }).then(r => !cancelled && setData(r)).catch(e => !cancelled && setError(errText(e))).finally(() => !cancelled && setLoading(false)); return () => { cancelled = true } }, [page])
  useEffect(() => { (data?.items || []).forEach(d => { if (calendars[d.id] || intervalErrors[d.id]) return; api.intervals(d.id).then(v => setCalendars(p => ({ ...p, [d.id]: v }))).catch(e => setIntervalErrors(p => ({ ...p, [d.id]: errText(e) }))) }) }, [data])
  const rows = useMemo(() => data?.items.filter(d => `${d.full_name} ${d.academic_group || ''}`.toLowerCase().includes(query.toLowerCase())) || [], [data, query]); const pages = Math.max(1, Math.ceil((data?.total || 0) / limit))
  return <section className="space-y-5"><div className="grid gap-3 md:grid-cols-3"><Stat value={String(data?.total ?? '—')} label="Всего доноров" detail="в активном реестре" /><Stat value="5 / 4" label="Лимит кроводач" detail="мужчины / женщины" tone="orange" /><Stat value="№ 1166н" label="Норматив" detail="расчёт интервалов" tone="blue" /></div><div className="overflow-hidden rounded-2xl border border-[#e1e8ec] bg-white shadow-[0_10px_35px_rgba(40,60,70,.04)]"><div className="flex flex-col gap-3 border-b border-[#e8edef] p-5 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="font-bold text-[#263847]">Список доноров</h2><p className="mt-1 text-xs text-[#8b99a3]">Проверка допуска обновляется автоматически</p></div><label className="relative block sm:w-64"><span className="absolute left-3 top-2.5 text-[#91a0aa]">⌕</span><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Поиск по ФИО или группе" className="w-full rounded-xl border border-[#dce5e9] bg-[#f8fafb] py-2 pl-9 pr-3 text-xs outline-none focus:border-[#55b8a4] focus:ring-2 focus:ring-[#dff5ee]" /></label></div>{loading ? <div className="flex justify-center py-20 text-[#168e78]"><Spinner /></div> : error ? <div className="p-8"><div className="rounded-xl bg-[#fff2f0] p-4 text-sm text-[#b54338]">{error}<button onClick={() => { setError(''); setPage(p => p) }} className="ml-3 font-bold underline">Повторить</button></div></div> : rows.length === 0 ? <Empty title="Доноры не найдены" text="Измените поисковый запрос или добавьте запись через API." /> : <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead className="bg-[#f8fafb] text-[10px] uppercase tracking-[.12em] text-[#8997a0]"><tr><th className="px-5 py-3">Донор</th><th className="px-4 py-3">Группа</th><th className="px-4 py-3">Фенотип</th><th className="px-4 py-3">Допуск</th><th className="px-4 py-3">Статус</th><th /></tr></thead><tbody className="divide-y divide-[#edf1f3]">{rows.map(d => <tr key={d.id} className="hover:bg-[#fbfdfd]"><td className="px-5 py-4"><button className="text-left" onClick={() => onSelect(d)}><p className="text-sm font-bold text-[#2d4250] hover:text-[#168e78]">{d.full_name}</p><p className="mt-1 text-[11px] text-[#98a4ac]">{d.academic_group || 'Группа не указана'}</p></button></td><td className="px-4 py-4 text-sm font-semibold text-[#526876]">{d.blood_group || '—'} <span className="text-[#168e78]">{d.rh_factor || ''}</span></td><td className="px-4 py-4 text-xs text-[#70818c]">Kell {d.kell_status || '—'}</td><td className="px-4 py-4"><Eligibility calendar={calendars[d.id]} loading={!calendars[d.id] && !intervalErrors[d.id]} error={intervalErrors[d.id]} /></td><td className="px-4 py-4"><Badge tone={d.status.toLowerCase() === 'active' ? 'good' : 'muted'}>{statusLabel(d.status)}</Badge></td><td className="px-5 py-4 text-right"><button onClick={() => onSelect(d)} className="text-lg text-[#9ba8af] hover:text-[#168e78]">›</button></td></tr>)}</tbody></table></div>}<div className="flex items-center justify-between border-t border-[#e8edef] px-5 py-3 text-xs text-[#8997a0]"><span>{data?.total ? `${page * limit + 1}–${Math.min((page + 1) * limit, data.total)} из ${data.total}` : '0 записей'}</span><div className="flex gap-1"><button disabled={page === 0} onClick={() => setPage(p => p - 1)} className="rounded-lg border border-[#dce5e9] px-3 py-1.5 disabled:opacity-40">Назад</button><span className="px-2 py-1.5 font-bold text-[#4c6471]">{page + 1} / {pages}</span><button disabled={page + 1 >= pages} onClick={() => setPage(p => p + 1)} className="rounded-lg border border-[#dce5e9] px-3 py-1.5 disabled:opacity-40">Далее</button></div></div></div></section>
}

type OCRResult = { status?: string; confidence_score?: number; is_duplicate?: boolean; raw_text?: string; masked_text?: string; extracted_data?: { student_id?: string | null; full_name?: string | null; academic_group?: string | null; donation_date?: string | null; donation_type_ru?: string | null; medical_center_short?: string | null; certificate_number?: string | null }; medical_intervals?: Record<string, string | null> }
type DonationRow = { id: string; donor_id: string; donor_full_name: string; academic_group?: string | null; donor_status: string; donation_date: string; donation_type: string; is_rewarded: boolean; medical_center?: string | null; certificate_number?: string | null }

function Certificate() {
  const [file, setFile] = useState<File>(), [task, setTask] = useState<OCRTask>(), [busy, setBusy] = useState(false), [error, setError] = useState(''), [donors, setDonors] = useState<Donor[]>([]), [rows, setRows] = useState<DonationRow[]>([]), [selectedDonor, setSelectedDonor] = useState(''), [fullName, setFullName] = useState(''), [group, setGroup] = useState(''), [center, setCenter] = useState(''), [certificate, setCertificate] = useState(''), [donationDate, setDonationDate] = useState(''), [donationType, setDonationType] = useState('Цельная кровь'), [saved, setSaved] = useState('')
  const result = task?.result as OCRResult | undefined; const data = result?.extracted_data
  const request = async (path: string, init?: RequestInit) => { const base = (import.meta.env.VITE_API_BASE_URL || '').replace(/\/$/, ''); const response = await fetch(`${base}/api/v1${path}`, { ...init, headers: { ...(init?.headers || {}), Authorization: `Bearer ${localStorage.getItem('donorflow_token') || ''}`, ...(init?.body instanceof FormData ? {} : { 'Content-Type': 'application/json' }) } }); if (!response.ok) { const payload = await response.json().catch(() => null); throw new Error(apiDetailText(payload?.detail || payload?.message) || 'Не удалось выполнить запрос') }; return response.status === 204 ? null : response.json() }
  const load = async () => { try { const [d, r] = await Promise.all([request('/donors?limit=100&offset=0'), request('/donations')]); setDonors(d.items || []); setRows(r || []) } catch (e) { setError(errText(e)) } }
  useEffect(() => { load() }, [])
  const apply = (preset: OCRResult) => { setTask({ task_id: 'preset', status: 'success', result: preset } as OCRTask); setSelectedDonor(preset.extracted_data?.student_id || 'new'); setFullName(preset.extracted_data?.full_name || ''); setGroup(preset.extracted_data?.academic_group || ''); setCenter(preset.extracted_data?.medical_center_short || ''); setCertificate(preset.extracted_data?.certificate_number || ''); setDonationDate(preset.extracted_data?.donation_date || ''); setDonationType(preset.extracted_data?.donation_type_ru || 'Цельная кровь') }
  const submit = async (selectedFile: File) => { setBusy(true); setError(''); setSaved(''); try { const initial = await api.uploadCertificate(selectedFile); setTask(initial); const final = ['success', 'completed'].includes(initial.status.toLowerCase()) ? initial : await pollOCR(initial.task_id, setTask); if (!['success', 'completed'].includes(final.status.toLowerCase())) throw new Error(final.error || 'Не удалось распознать справку'); setTask(final); const r = final.result as OCRResult | undefined; setSelectedDonor(r?.extracted_data?.student_id || 'new'); setFullName(r?.extracted_data?.full_name || ''); setGroup(r?.extracted_data?.academic_group || ''); setCenter(r?.extracted_data?.medical_center_short || ''); setCertificate(r?.extracted_data?.certificate_number || ''); setDonationDate(r?.extracted_data?.donation_date || ''); setDonationType(r?.extracted_data?.donation_type_ru || 'Цельная кровь') } catch (e) { setError(errText(e)) } finally { setBusy(false) } }
  const save = async () => { if (!result || result.is_duplicate) return; setBusy(true); setError(''); try { let donorId = selectedDonor; const correctedFullName = fullName.trim(); if (donorId === 'new') { if (!correctedFullName) throw new Error('Не удалось распознать ФИО нового донора. Выберите существующего донора или загрузите справку повторно.'); const gender = inferredGender(correctedFullName) || 'male'; const created = await request('/donors', { method: 'POST', body: JSON.stringify({ full_name: correctedFullName, gender, academic_group: group.trim() || null, blood_group: null, rh_factor: null, kell_status: null }) }); donorId = created.id } await request(`/donations/${crypto.randomUUID()}/verify`, { method: 'PUT', body: JSON.stringify({ donor_id: donorId, donation_date: donationDate, donation_type: donationTypeValue(donationType), medical_center: center, certificate_number: certificate }) }); setSaved(`Справка № ${certificate} (${correctedFullName || data?.full_name || 'донор'}, ${donationDate}) верифицирована и сохранена в БД.`); await load() } catch (e) { setError(errText(e)) } finally { setBusy(false) } }
  const preset = (kind: number) => apply({ status: 'success', confidence_score: .97, is_duplicate: kind === 2, raw_text: kind === 3 ? 'СПРАВКА № 143119\\nПлазмаферез / Тромбоциты' : 'СПРАВКА № 143117\\nКнязева Милана Игоревна\\n07.10.2026', masked_text: 'СПРАВКА № 143117\\n[ПАСПОРТ_СКРЫТ_ФЗ152] [СНИЛС_СКРЫТ_ФЗ152] [ТЕЛЕФОН_СКРЫТ_ФЗ152]', extracted_data: { full_name: kind === 3 ? 'Тестовый Донор' : 'Князева Милана Игоревна', academic_group: 'Кс-33', donation_date: '2026-10-07', donation_type_ru: kind === 3 ? 'Плазма' : 'Цельная кровь', medical_center_short: 'ОПК РХТУ', certificate_number: `14311${6 + kind}` }, medical_intervals: { status_comment: 'Следующий допуск рассчитывается после регистрации справки.' } })
  return <section className="space-y-6"><div className="rounded-2xl border border-[#e1e8ec] bg-white p-6 shadow-[0_10px_35px_rgba(40,60,70,.04)]"><div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div><h2 className="text-xl font-bold text-[#263847]">Конвейер OCR (ф. 447/у), Обезличивание ФЗ-152 и Антифрод-верификация</h2><p className="mt-2 text-sm text-[#84939d]">Автоматическое извлечение ФИО, даты, типа донации и ОПК с проверкой уникального индекса (donor_id, donation_date)</p></div><label className="shrink-0 cursor-pointer rounded-xl bg-[#168e78] px-4 py-3 text-sm font-bold text-white">Загрузить файл справки (JPG / PDF / PNG)<input type="file" accept="image/jpeg,image/png,image/tiff,.pdf" className="sr-only" onChange={e => { const selectedFile = e.target.files?.[0]; e.currentTarget.value = ''; if (!selectedFile) return; setFile(selectedFile); setTask(undefined); setError(''); void submit(selectedFile) }} /></label></div><div className="mt-5 flex flex-wrap items-center gap-2"><span className="text-xs font-bold text-[#516673]">Тестовые пресеты сканов справок ф. 447/у</span>{['Новая справка Цельная кровь', 'Тест АНТИФРОДА', 'Плазмаферез / Тромбоциты'].map((label, i) => <button key={label} onClick={() => preset(i + 1)} className="rounded-lg border border-[#bfe4d8] px-3 py-2 text-xs font-bold text-[#168e78]">{label}</button>)}</div></div>{saved && <div className="rounded-xl border border-[#bfe4d8] bg-[#e5f7ee] p-4 text-sm font-semibold text-[#14754b]">{saved}</div>}{error && <div className="rounded-xl bg-[#fff2f0] p-4 text-sm text-[#b54338]">{error}</div>}{result && <div className="grid grid-cols-1 gap-6 lg:grid-cols-2"><div className="rounded-2xl border border-[#e1e8ec] bg-white p-6"><h3 className="font-bold text-[#263847]">1. Распознанный сырой текст со скана справки ф. 447/у (Tesseract / EasyOCR)</h3><pre className="mt-3 h-44 overflow-y-auto whitespace-pre-wrap rounded-lg border bg-slate-50 p-3 font-mono text-xs">{result.raw_text || '—'}</pre><div className="mt-5 flex items-center justify-between gap-3"><h3 className="font-bold text-[#263847]">2. Препроцессор обезличивания ПДн (ФЗ № 152-ФЗ) перед отправкой в LLM</h3><Badge tone="good">Паспорт / СНИЛС / Телефон скрыты</Badge></div><pre className="mt-3 h-44 overflow-y-auto whitespace-pre-wrap rounded-lg bg-slate-900 p-3 font-mono text-xs text-slate-100">{result.masked_text || '—'}</pre></div><div className="rounded-2xl border border-[#e1e8ec] bg-white p-6"><div className="flex items-center justify-between"><h3 className="font-bold text-[#263847]">3. Верификация карточки координатором и проверка антифрода</h3><Badge tone={result.is_duplicate ? 'bad' : 'good'}>{result.is_duplicate ? 'АНТИФРОД: ДУБЛИКАТ ЗАБЛОКИРОВАН' : 'АНТИФРОД: ПРОЙДЕН'}</Badge></div><p className="mt-3 text-xs text-[#516673]">Confidence Score: {result.confidence_score ?? '—'}</p><label className="mt-4 block text-xs font-bold text-[#516673]">Сопоставленный студент в базе РХТУ (авто-матчинг по ФИО)<select value={selectedDonor} onChange={e => setSelectedDonor(e.target.value)} className="mt-2 w-full rounded-xl border border-[#dce5e9] px-3 py-2.5 text-sm"><option value="new">+ Новый студент: {data?.full_name || 'не распознано'}</option>{donors.map(d => <option key={d.id} value={d.id}>{d.full_name} {d.academic_group ? `(${d.academic_group})` : ''}</option>)}</select></label>{selectedDonor === 'new' && <div className="mt-4 grid gap-4 sm:grid-cols-2"><Field label="ФИО студента (проверьте опечатки OCR)" value={fullName} onChange={setFullName} /><Field label="Группа (напр. Кс-33)" value={group} onChange={setGroup} /></div>}<div className="mt-4 grid gap-4 sm:grid-cols-2"><Field label="Дата донации" type="date" value={donationDate} onChange={setDonationDate} /><label className="block"><span className="mb-2 block text-xs font-bold text-[#516673]">Тип донации</span><select value={donationType} onChange={e => setDonationType(e.target.value)} className="w-full rounded-xl border border-[#dce5e9] px-3 py-2.5 text-sm"><option>Цельная кровь</option><option>Плазма</option><option>Тромбоциты</option></select></label></div><div className="mt-4 grid gap-4 sm:grid-cols-2"><Field label="Номер справки ф. 447/у" value={certificate} onChange={setCertificate} /><Field label="Медицинский центр (ОПК)" value={center} onChange={setCenter} /></div><div className="mt-4 rounded-lg border bg-slate-50 p-3 text-xs"><strong>Прогноз медицинского интервала после регистрации справки:</strong><p className="mt-1">{result.medical_intervals?.status_comment || '—'}</p></div><button disabled={busy || result.is_duplicate} onClick={save} className="mt-5 w-full rounded-xl bg-[#168e78] px-4 py-3 text-sm font-bold text-white disabled:bg-[#d05a50]">{result.is_duplicate ? 'Заблокировано антифродом (Дубликат ФИО + Дата)' : 'Верифицировать и сохранить в БД'}</button></div></div>}{<div className="overflow-hidden rounded-2xl border border-[#e1e8ec] bg-white"><div className="flex items-center justify-between p-6"><h3 className="font-bold text-[#263847]">Реестр оцифрованных справок ф. 447/у ({rows.length})</h3><span className="text-xs text-[#84939d]">Биллинг СЗ защищает от повторного включения справки в приказы на поощрение</span></div><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left text-xs"><thead className="bg-[#f8fafb] text-[10px] uppercase text-[#8997a0]"><tr>{['Дата', 'ФИО студента', 'Группа', 'Вид донации', 'ОПК и № справки', 'Биллинг СЗ', 'Действие'].map(h => <th key={h} className="px-4 py-3">{h}</th>)}</tr></thead><tbody className="divide-y divide-[#edf1f3]">{rows.map(row => <tr key={row.id}><td className="px-4 py-3">{fmtDate(row.donation_date)}</td><td className="px-4 py-3 font-semibold">{row.donor_full_name}</td><td className="px-4 py-3">{row.academic_group || '—'}</td><td className="px-4 py-3">{row.donation_type}</td><td className="px-4 py-3">{row.medical_center || '—'} · {row.certificate_number || '—'}</td><td className="px-4 py-3"><Badge tone={row.is_rewarded ? 'good' : 'warn'}>{row.is_rewarded ? 'true' : 'false'}</Badge></td><td className="px-4 py-3"><button onClick={() => request(`/donations/${row.id}`, { method: 'DELETE' }).then(load).catch(e => setError(errText(e)))} className="font-bold text-[#b54338]">Удалить</button></td></tr>)}</tbody></table></div></div>}</section>
}

type RegistryDonation = { id: string; donation_date: string; donation_type: string; is_rewarded: boolean; medical_center?: string | null; certificate_number?: string | null }
type RegistryCalendar = IntervalCalendar & { donor: Donor & { donations?: RegistryDonation[] } }
type ImportPreview = { headers: string[]; rows: Record<string, string>[]; total: number }
type DonorDraft = { full_name: string; gender: string; academic_group: string; blood_group: string; rh_factor: string; kell_status: string }
